mapper.insert:
insert into inv_transfer_approval_instance (
    transfer_id, rule_id, rule_name, rule_snapshot, status,
    current_node_order, approval_mode, required_count, reject_action,
    allow_self_approve, create_by, create_time, remark
) values (
    #{transferId}, #{ruleId}, #{ruleName}, #{ruleSnapshot}, #{status},
    #{currentNodeOrder}, #{approvalMode}, #{requiredCount}, #{rejectAction},
    #{allowSelfApprove}, #{createBy}, sysdate(), #{remark}
)

mapper.update:
update inv_transfer_approval_instance
set status = 'closed',
    update_by = #{updateBy},
    update_time = sysdate(),
    remark = left(concat_ws(
        '；', nullif(trim(remark), ''), #{reason}
    ), 500)
where transfer_id = #{transferId}
  and status = 'running'

update inv_transfer_approval_instance
status = #{status}, current_node_order = #{currentNodeOrder}, update_by = #{updateBy}, update_time = sysdate()
where instance_id = #{instanceId}
